struct Args<'a> {
    words: std::str::SplitWhitespace<'a>,
}

impl<'a> Args<'a> {
    fn word(&mut self) -> &'a str {
        self.words.next().expect("missing argument")
    }

    fn number(&mut self) -> u64 {
        self.word().parse().expect("numeric argument")
    }

    fn format(&mut self) -> WaveFormat {
        WaveFormat {
            format_tag: self.number() as u16,
            channels: self.number() as u16,
            samples_per_sec: self.number() as u32,
            avg_bytes_per_sec: self.number() as u32,
            block_align: self.number() as u16,
            bits_per_sample: self.number() as u16,
        }
    }
}

fn code(result: Result<(), Error>) -> u32 {
    match result {
        Ok(()) => 0,
        Err(e) => e.code(),
    }
}

fn format_text(f: &WaveFormat) -> String {
    format!(
        "{} {} {} {} {} {}",
        f.format_tag,
        f.channels,
        f.samples_per_sec,
        f.avg_bytes_per_sec,
        f.block_align,
        f.bits_per_sample
    )
}

fn hex_text(bytes: &[u8]) -> String {
    if bytes.is_empty() {
        return "-".to_string();
    }
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn parse_hex(text: &str) -> Vec<u8> {
    (0..text.len() / 2)
        .map(|i| u8::from_str_radix(&text[2 * i..2 * i + 2], 16).expect("hex byte"))
        .collect()
}

/// Runs one harness command line and returns the harness output line.
fn replay(command: &str) -> String {
    let mut args = Args {
        words: command.split_whitespace(),
    };
    match args.word() {
        "index" => {
            let fmt = WaveFormat {
                channels: args.number() as u16,
                samples_per_sec: args.number() as u32,
                bits_per_sample: args.number() as u16,
                ..Default::default()
            };
            format_index(&fmt).unwrap_or(u32::MAX).to_string()
        }
        "tagdetails" => {
            let query = args.number() as u32;
            let mut d = FormatTagDetails {
                index: args.number() as u32,
                format_tag: args.number() as u32,
                ..Default::default()
            };
            let rc = code(format_tag_details(query, &mut d));
            format!(
                "{rc} {} {} {} {} {}",
                d.index, d.format_tag, d.support, d.format_size, d.standard_formats
            )
        }
        "details" => {
            let query = args.number() as u32;
            let mut d = FormatDetails {
                format_index: args.number() as u32,
                ..Default::default()
            };
            let mut fmt = args.format();
            let rc = code(format_details(query, &mut d, &mut fmt));
            format!(
                "{rc} {} {} {} {}",
                d.format_tag,
                d.support,
                d.cb_wfx,
                format_text(&fmt)
            )
        }
        "suggest" => {
            let s = Suggest {
                fdw_suggest: args.number() as u32,
                cb_src: args.number() as u32,
                cb_dst: args.number() as u32,
            };
            let src = args.format();
            let mut dst = args.format();
            let rc = code(format_suggest(&s, &src, &mut dst));
            format!("{rc} {}", format_text(&dst))
        }
        "size" => {
            let mut s = StreamSize {
                fdw_size: args.number() as u32,
                src_length: args.number() as u32,
                dst_length: args.number() as u32,
            };
            let src = args.format();
            let dst = args.format();
            let rc = code(stream_size(&src, &dst, &mut s));
            format!("{rc} {} {}", s.src_length, s.dst_length)
        }
        "open" => {
            let fdw_open = args.number() as u32;
            let src = args.format();
            let dst = args.format();
            match stream_open(fdw_open, &src, &dst) {
                Ok(conv) => format!("0 {} {}", u8::from(conv.resamples()), conv.table_index()),
                Err(e) => format!("{} 0 -1", e.code()),
            }
        }
        "convert" => {
            let src = args.format();
            let dst = args.format();
            let cb_src = args.number() as usize;
            let cb_dst = args.number() as usize;
            let hex = args.word();
            match stream_open(0, &src, &dst) {
                Err(e) => format!("{} - -", e.code()),
                Ok(conv) => {
                    let mut input = if hex == "-" {
                        Vec::new()
                    } else {
                        parse_hex(hex)
                    };
                    // The harness converts cbSrcLength bytes of a zero-filled buffer.
                    input.resize(cb_src, 0);
                    let mut out = vec![0xAA; cb_dst];
                    let usage = conv.convert(&input, &mut out);
                    format!("0 {} {} {}", usage.src_used, usage.dst_used, hex_text(&out))
                }
            }
        }
        "driver" => {
            let d = driver_details();
            format!(
                "0 {} {} {} {} {} {} {} {} {} {}|{}|{}|{}|{}",
                d.fcc_type,
                d.fcc_comp,
                d.manufacturer_id,
                d.product_id,
                d.acm_version,
                d.driver_version,
                d.support,
                d.format_tags,
                d.filter_tags,
                d.short_name,
                d.long_name,
                d.copyright,
                d.licensing,
                d.features
            )
        }
        "drvopen" => {
            let fcc_type = args.number() as u32;
            let fcc_comp = args.number() as u32;
            let desc = OpenDescription { fcc_type, fcc_comp };
            let null = args.number() != 0;
            let accepted = driver_open_accepts(if null { None } else { Some(&desc) });
            u8::from(accepted).to_string()
        }
        other => panic!("unknown harness command {other}"),
    }
}

#[test]
fn oracle_vectors_match_wine() {
    for &(command, expected) in VECTORS {
        assert_eq!(replay(command), expected, "{command}");
    }
}

#[test]
fn edge_vectors_match_wine() {
    for &(command, expected) in EDGE_VECTORS {
        assert_eq!(replay(command), expected, "{command}");
    }
}

#[test]
#[should_panic(expected = "unknown harness command bogus")]
fn unknown_command_panics() {
    replay("bogus");
}
